import React, { useEffect, useState } from 'react';
import Modal from "../../Templates/Modal/Modal";
import axios from "axios";
import './Role.css'

function Role({ modalActiveRole, setModalActiveRole,username}) {

    const [roles, setRoles] = useState([]);
    const [checkedItems, setCheckedItems] = useState({});
    const [user, setUser] = useState([])
    const [check, setCheck] = useState();
    useEffect(() => {
        const fetchData = async () => {
            try {
                const resRoles = await axios.get('/api/roles/');
                const rolesData = resRoles.data[0].get_roles;
                setRoles(rolesData);
                const res = await axios.get('/api/user/' + username.username)
                setUser(res.data)
                console.log('user.role_id =',user.role_id )
            } catch (error) {
                console.error('Error fetching data:', error);
            }
        };

        fetchData();
    }, []);

    const inputClickRole = (event, voteId) => {
        const {id, checked} = event.target
        if (checked) {
            setCheckedItems(checked)
        } else {
            setCheckedItems(null)
        }
        setCheck(event.target.value)

        setCheckedItems(prevState => ({
            ...prevState,
            [id]: checked,
        }))
        setUser(prevState => ({
                ...prevState,
                nomination_status: checked ? voteId : null
            }
        ))
    }


    return (
        <Modal active={modalActiveRole} setActive={setModalActiveRole}>
            <h1>Назначить роль:</h1>
            <hr />
            <div>
                <div className='voteContainer'>
                    {roles.map((role, id) => (
                        <div key={id} className="voteItem">
                            <label key={id} className="inputVote">
                                <input
                                    type='checkbox'
                                    id={role.id}
                                    value={role.id}
                                    checked={user.role_id === role.id}
                                    onChange={(e) => inputClickRole(e, role.id)}
                                />
                                {role.name}
                            </label>
                        </div>
                    ))}
                </div>
            </div>
        </Modal>
    );
}

export default Role;
